def wants_help(command, rest):
    """Whether ``--help`` appears on the line as an option, not as the value
    of ``report``'s ``--format`` (``--dir``'s value is already out of ``rest``)."""
    i = 0
    while i < len(rest):
        if rest[i] == "--help":
            return True
        if command == "report" and i > 0 and rest[i] == "--format":
            i += 1  # the next argument is its value, whatever it is
        i += 1
    return False

